package dev.aura.player;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;
@RunWith(AndroidJUnit4.class)
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class DriveCastScopeTest {
 final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();final Uri provider=Uri.parse("content://dev.aura.player.test.documents");
 @After public void cleanup(){DriveAuth.get(c).clear();c.getContentResolver().call(provider,"test.reset",null,null);}
 DriveHttp http(DriveTest.FakeDrive server){return new DriveHttp(server.base(),new DriveHttp.Tokens(){public String token(){return "fake-access";}public void invalidate(String old){}});}
 @Test public void receiverGetsOnlyRequestedDriveBytesWithNoCredentials()throws Exception{try(var drive=new DriveTest.FakeDrive();var relay=new MediaFileServer(c,()->"127.0.0.1")){AtomicBoolean allowed=new AtomicBoolean(true);String url=relay.publish(new DriveRelaySource(DriveUris.file("test","song","Tone.wav"),"audio/wav",http(drive),allowed::get));assertFalse(url.contains("fake-access"));HttpURLConnection head=(HttpURLConnection)new URL(url).openConnection();head.setRequestMethod("HEAD");assertEquals(200,head.getResponseCode());assertEquals(drive.total,head.getContentLengthLong());head.disconnect();assertTrue(drive.requests.stream().noneMatch(r->r.path().contains("alt=media")));for(String range:List.of("bytes=0-3","bytes=500001-500128","bytes=-16")){HttpURLConnection request=(HttpURLConnection)new URL(url).openConnection();request.setRequestProperty("Range",range);try{assertEquals(206,request.getResponseCode());assertEquals("audio/wav",request.getContentType());byte[] data=Io.read(request.getInputStream());int from=range.equals("bytes=0-3")?0:range.equals("bytes=-16")?drive.total-16:500001;assertEquals(range.equals("bytes=0-3")?4:range.equals("bytes=-16")?16:128,data.length);for(int i=0;i<data.length;i++)assertEquals(drive.audio(from+i),data[i]);assertFalse(request.getHeaderFields().toString().contains("fake-access"));}finally{request.disconnect();}}assertTrue(drive.sent.get()<4L*DriveDataSource.WINDOW);allowed.set(false);HttpURLConnection denied=(HttpURLConnection)new URL(url).openConnection();assertEquals(502,denied.getResponseCode());denied.disconnect();relay.clear();HttpURLConnection gone=(HttpURLConnection)new URL(url).openConnection();assertEquals(404,gone.getResponseCode());gone.disconnect();}}
 @Test public void receiverPreflightAndBadRangesDoNotDownloadAudio()throws Exception{try(var drive=new DriveTest.FakeDrive();var relay=new MediaFileServer(c,()->"127.0.0.1")){String url=relay.publish(new DriveRelaySource(DriveUris.file("test","song","Tone.wav"),"audio/wav",http(drive),()->true));var options=(HttpURLConnection)new URL(url).openConnection();options.setRequestMethod("OPTIONS");assertEquals(204,options.getResponseCode());assertTrue(options.getHeaderField("Access-Control-Allow-Headers").contains("Range"));options.disconnect();for(String range:List.of("bytes=-0","bytes=-","bytes=9-1","bytes=9999999999-","bytes=1-2,5-6","bytes=999999999999999999999999999999-")){var r=(HttpURLConnection)new URL(url).openConnection();r.setRequestProperty("Range",range);assertEquals(416,r.getResponseCode());assertEquals("bytes */"+drive.total,r.getHeaderField("Content-Range"));r.disconnect();}assertTrue(drive.requests.stream().noneMatch(r->r.path().contains("alt=media")));}}
 @Test public void localScopeRefreshesOnlySelectedSubfolder()throws Exception{c.getContentResolver().call(provider,"test.reset",null,null);Uri a=DocumentsContract.buildTreeDocumentUri(provider.getAuthority(),"A"),b=DocumentsContract.buildTreeDocumentUri(provider.getAuthority(),"B");Library.saveRoots(c,List.of(a,b));var library=new Library(c);var tracks=library.scan(List.of(a,b),p->{});Track nested=tracks.stream().filter(t->t.uri.contains("b.wav")).findFirst().orElseThrow();var scope=new FolderScope(false,a.toString(),"A/sub",nested.folderPath);assertEquals(scope,FolderScope.from(scope.json()));var before=c.getContentResolver().call(provider,"test.stats",null,null);c.getContentResolver().call(provider,"test.change",null,null);var afterTracks=library.scanFolder(scope,p->{});var after=c.getContentResolver().call(provider,"test.stats",null,null);assertEquals(before.getInt("open:A/a.wav"),after.getInt("open:A/a.wav"));assertEquals(before.getInt("open:B/c.wav"),after.getInt("open:B/c.wav"));assertTrue(after.getInt("open:A/sub/b.wav")>before.getInt("open:A/sub/b.wav"));assertEquals(3,afterTracks.size());assertTrue(afterTracks.stream().anyMatch(t->t.uri.contains("a.wav")));assertFalse(afterTracks.stream().anyMatch(t->t.uri.contains("new.wav")));}
 @Test public void driveScopeDeletesOnlyInsideAndPreservesOtherFoldersAndCursor()throws Exception{DriveAuth.get(c).accept("scope","scope@example.invalid","테스트","fake");DriveLibrary.saveRoots(c,List.of(new DriveLibrary.Folder("root","Music")));try(var server=new IncrementalLibraryTest.Server()){AtomicInteger tags=new AtomicInteger();var library=new DriveLibrary(c,new DriveApi(new DriveHttp(server.base(),new DriveHttp.Tokens(){public String token(){return "fake";}public void invalidate(String t){}})),(context,row,generation)->{tags.incrementAndGet();return row.put("enriched",true);});var tracks=library.scan(p->{});assertEquals(3,tags.get());var nested=tracks.stream().filter(t->t.folderId.equals("sub")).findFirst().orElseThrow();var scope=new FolderScope(true,"root","sub",nested.folderPath);server.files.put("sub",new JSONArray());server.listings.clear();var result=library.scanFolder(scope,p->{});assertEquals(2,result.size());assertEquals(List.of("sub"),server.listings);assertEquals(3,tags.get());assertTrue(result.stream().anyMatch(t->t.folderId.equals("quiet")));String previous=new String(java.nio.file.Files.readAllBytes(new File(c.getFilesDir(),"drive-library.json").toPath()),StandardCharsets.UTF_8);server.failedFolder="sub";try{library.scanFolder(scope,p->{});fail("Missing folder response accepted");}catch(IOException expected){}assertEquals(previous,new String(java.nio.file.Files.readAllBytes(new File(c.getFilesDir(),"drive-library.json").toPath()),StandardCharsets.UTF_8));}}
 @Test public void naturalNumbersAndFilePrefixesSortWithoutAudioRescan(){Track ten=new Track("file:///Music/10%20Song.flac","Song 10","","","",0,""),two=new Track("file:///Music/2%20Song.flac","Song 2","","","",0,"");assertEquals(2,two.orderTrack);assertEquals(List.of(two,ten),TrackOrder.sorted(List.of(ten,two),"track",false));assertEquals(List.of(two,ten),TrackOrder.sorted(List.of(ten,two),"title",false));Track tagged=ten.withNumbers(1,1);assertEquals(List.of(tagged,two),TrackOrder.sorted(List.of(two,tagged),"track",false));}
}
